<template>
  <div v-loading="loading" element-loading-text="测试中...">
    <el-form
      :model="ruleForm"
      ref="ruleForm"
      label-width="130px"
      class="demo-ruleForm mt-30"
      size="small"
    >
      <el-form-item label="时间同步方式:" prop="sync_method">
        <el-select
          v-model="ruleForm.sync_method"
          clearable
          @change="changeMethod"
        >
          <el-option label="同步系统配置时间" :value="1"></el-option>
          <el-option label="同步NTP服务器时间" :value="2"></el-option>
        </el-select>
      </el-form-item>
      <el-form-item label="时区:" prop="time_zone">
        <el-select
          v-model="ruleForm.time_zone"
          clearable
          style="width: 45%"
          :disabled="ruleForm.sync_method == 2 || !issync"
          @change="changeTimeZone"
        >
          <el-option
            :label="item"
            :value="index"
            v-for="(item, index) in timeZoneList"
            :key="index"
          ></el-option>
        </el-select>
      </el-form-item>
      <el-form-item label="系统时间:" prop="tool_url">
        {{ currentTime || "--" }}</el-form-item
      >
      <el-form-item label="设置时间:" prop="tool_url">
        <el-date-picker
          v-model="date_time"
          type="datetime"
          placeholder="选择日期时间"
          format="yyyy-MM-dd HH:mm:ss"
          :disabled="!issync"
        >
        </el-date-picker>
        <el-button
          size="mini"
          class="ml-10"
          @click="synchronous"
          :disabled="ruleForm.sync_method == 2"
        >
          {{ issync ? "同步计算机时间" : "取消同步" }}</el-button
        >
      </el-form-item>
      <template v-if="ruleForm.sync_method == 2">
        <el-divider content-position="left" class="mt-50"
          ><span class="f-bold">NTP服务器</span>
        </el-divider>
        <el-form-item label="NTP服务器地址:" prop="ntp_address">
          <el-input v-model="ruleForm.ntp_address" style="width: 30%" />
          <el-button size="mini" class="ml-10" @click="verificationNtp"
            >测试</el-button
          >
        </el-form-item>
        <el-form-item label="NTP服务器地址:" prop="ntp_interval">
          <el-input-number v-model="ruleForm.ntp_interval" />
        </el-form-item>
      </template>
      <el-form-item>
        <el-button type="primary" @click="submitForm('ruleForm')">
          保存
        </el-button>
      </el-form-item>
    </el-form>
  </div>
</template>

<script>
export default {
  data() {
    return {
      ruleForm: {
        time_zone: 27,
        sync_method: 1,
      },
      timeZoneList: [
        "UTC-12:00 国际日期变更线西",
        "UTC-11:00 萨摩亚群岛",
        "UTC-10:00 夏威夷、帕皮提",
        "UTC-09:00 阿拉斯加",
        "UTC-08:00 太平洋时间（洛杉矶、温哥华、提华纳）",
        "UTC-07:00 山地时间（凤凰、丹佛、卡尔加里、华雷斯）",
        "UTC-06:00 中部时间（芝加哥、危地马拉、墨西哥、圣何塞）",
        "UTC-05:00 东部时间（纽约、多伦多、波哥大）",
        "UTC-04:30 加拉加斯",
        "UTC-04:00 大西洋时间（圣地亚哥、圣多明哥）",
        "UTC-03:30 纽芬兰",
        "UTC-03:00 圣保罗、布宜诺斯艾利斯",
        "UTC-02:00 中大西洋",
        "UTC-01:00 普拉亚、亚速尔群岛",
        "UTC+00:00 伦敦、都柏林、里斯本",
        "UTC+01:00 柏林、罗马、巴黎、马德里、华沙",
        "UTC+02:00 开罗、耶路撒冷、雅典",
        "UTC+03:00 莫斯科、伊斯坦布尔、巴格达、多哈",
        "UTC+03:30 德黑兰",
        "UTC+04:00 阿布扎比、巴库",
        "UTC+04:30 喀布尔",
        "UTC+05:00 伊斯兰堡、卡拉奇、塔什干、叶卡捷琳堡",
        "UTC+05:30 孟买、新德里、科伦坡",
        "UTC+05:45 加德满都",
        "UTC+06:00 达卡、阿拉木图、鄂木斯克",
        "UTC+06:30 仰光",
        "UTC+07:00 雅加达、曼谷、胡志明市、河内",
        "UTC+08:00 北京、香港特别行政区、乌鲁木齐、新加坡、台北、珀斯",
        "UTC+09:00 东京、大阪、首尔、雅库茨克",
        "UTC+09:30 阿德莱德、达尔文",
        "UTC+10:00 墨尔本、悉尼、海参崴",
        "UTC+11:00 所罗门群岛、马加丹",
        "UTC+12:00 惠灵顿、奥克兰、苏瓦",
        "UTC+13:00 凤凰群岛、努库阿洛法",
      ],
      timer: null,
      timer1: null,
      currentTime: "",
      setTime: "",
      loading: false,
      issync: true,
      date_time: "",
    };
  },
  created() {},
  mounted() {
    this.getData();
    this.getSysClockTimes();
    this.timer = setInterval(() => {
      this.getSysClockTimes();
    }, 1000);
  },
  beforeDestroy() {
    if (this.timer) {
      clearInterval(this.timer);
    }
    if (this.timer1) {
      clearInterval(this.timer1);
    }
  },
  methods: {
    // 获取数据
    getData() {
      this.$api.get(`/sys/getSysClock`).then((res) => {
        this.ruleForm = res.data.data || {
          time_zone: 27,
          sync_method: 1,
        };
        if (this.timer1) {
          clearInterval(this.timer1);
          this.issync = true;
        }
        this.updateTime("date_time");
      });
    },
    // 测试
    verificationNtp() {
      this.loading = true;
      this.$api
        .post("/sys/verificationNtp", {
          ntp_address: this.ruleForm.ntp_address,
        })
        .then((res) => {
          this.loading = false;
          this.$message.success(res.data.msg);
        })
        .finally(() => {
          this.loading = false;
        });
    },
    // 获取系统时间
    getSysClockTimes() {
      this.$api.get(`/sys/getSysClockTimes`).then((res) => {
        this.currentTime = res.data.data;
      });
    },
    // 同步
    synchronous() {
      this.issync = !this.issync;
      this.ruleForm.time_zone = 27;
      if (!this.issync) {
        clearInterval(this.timer1);
        this.timer1 = null;

        this.timer1 = setInterval(() => {
          this.updateTime("date_time");
        }, 1000);
      } else {
        clearInterval(this.timer1);
        this.timer1 = null;
      }
    },
    // 切换方式
    changeMethod(e) {
      if (e == 1) {
        this.ruleForm.ntp_address = undefined;
        this.ruleForm.ntp_interval = undefined;
      } else {
        this.ruleForm.ntp_interval = 600;
        if (this.timer1) {
          clearInterval(this.timer1);
        }
        this.getSysClockTimes();
      }
    },
    // 时区转换
    changeTimeZone(e) {
      const utcString = this.timeZoneList[e].trim().split(/\s+/)[0];
      // 解析UTC字符串，提取时区偏移
      const utcRegex = /^UTC([+-])(\d{2}):(\d{2})$/;
      const match = utcString.match(utcRegex);

      if (!match) {
        throw new Error("无效的UTC格式");
      }
      const sign = match[1];
      const hours = parseInt(match[2]);
      const minutes = parseInt(match[3]);
      // 计算总偏移小时数
      const offsetHours =
        sign === "+" ? hours + minutes / 60 : -(hours + minutes / 60);
      // 获取当前UTC时间
      const now = new Date();
      const utc = now.getTime() + now.getTimezoneOffset() * 60000;
      // 计算目标时区时间
      const targetTime = new Date(utc + 3600000 * offsetHours);
      // 格式化输出
      const year = targetTime.getFullYear();
      const month = String(targetTime.getMonth() + 1).padStart(2, "0");
      const day = String(targetTime.getDate()).padStart(2, "0");
      const hours24 = String(targetTime.getHours()).padStart(2, "0");
      const minutes2 = String(targetTime.getMinutes()).padStart(2, "0");
      const seconds = String(targetTime.getSeconds()).padStart(2, "0");
      this.date_time = `${year}-${month}-${day} ${hours24}:${minutes2}:${seconds}`;
    },
    // 时间
    updateTime(time) {
      const now = new Date();
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, "0");
      const day = String(now.getDate()).padStart(2, "0");
      const hours = String(now.getHours()).padStart(2, "0");
      const minutes = String(now.getMinutes()).padStart(2, "0");
      const seconds = String(now.getSeconds()).padStart(2, "0");
      this[time] = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    },
    // 提交表单
    submitForm() {
      this.ruleForm.date_time = this.date_time;
      this.$api.post("/sys/updateSysClock", this.ruleForm).then(() => {
        this.$message.success("操作成功！");
        this.getData();
      });
    },
  },
};
</script>

